//! 🧪️ Saved Window Pack/SPR sources reach the real native Store and retain exact receipts through both original source shapes.
use super::*;
use crate::original_genesis_tests::{Owner,State};
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OperationId,Generation,default_now_us};
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
use semio_framework_value::{ToValue,FromValue};
thread_local!{static INITIALIZER_PHASE:std::cell::RefCell<String>=const{std::cell::RefCell::new(String::new())};static LAST:std::cell::Cell<(u8,u16,usize,usize)>=const{std::cell::Cell::new((254,0,0,0))};}
fn note(load:&Option<WindowConfigPackLoad>){INITIALIZER_PHASE.with(|phase|{let value=load.as_ref().and_then(|load|load.inner.as_ref()).and_then(|owner|owner.as_any().downcast_ref::<TypedWindowConfigPackLoad<Owner>>()).and_then(|owner|owner.initializer.as_ref()).map_or_else(String::new,|initializer|format!("{:?}",initializer.phase));*phase.borrow_mut()=value;});let cursor=load.as_ref().and_then(|load|load.inner.as_ref()).and_then(|owner|owner.as_any().downcast_ref::<TypedWindowConfigPackLoad<Owner>>()).map_or((255,0,0,0),|owner|(owner.stage,u16::from(owner.sources_close.is_some())|u16::from(owner.factory.is_some())<<1|u16::from(owner.receiver.is_some())<<2|u16::from(owner.wire.is_some())<<3|u16::from(owner.fold_job.is_some())<<4|u16::from(owner.pair.is_some())<<5|u16::from(owner.initializer.is_some())<<6|u16::from(owner.history_source.is_some())<<7|u16::from(owner.metadata_close.is_some())<<8|u16::from(owner.candidate.is_some())<<9,owner.edit_index,owner.operation_index));LAST.with(|value|value.set(cursor));}
fn law()->serde_json::Value{serde_json::from_str(include_str!("🔣️.json")).unwrap()}
fn block<F:std::future::Future>(future:F)->F::Output{let mut future=Box::pin(future);let waker=std::task::Waker::noop();let mut cx=std::task::Context::from_waker(waker);loop{if let std::task::Poll::Ready(value)=future.as_mut().poll(&mut cx){return value}std::thread::yield_now()}}
pub(in crate::retained) fn input(framed:bool)->WindowConfigPack{let law=law();let window=law["window"].as_str().unwrap();let mut history=HistoryLog{doc_id:format!("window-config:{}:{window}",Owner::WINDOW_KIND_ID),schema:Owner::SCHEMA.into(),..Default::default()};for(index,zoom)in law["zooms"].as_array().unwrap().iter().enumerate(){let value=serde_json::json!({"kind":"zoom","zoom":zoom});let bytes=serde_json::to_vec(&value).unwrap();let mut wire=b"op".to_vec();wire.extend_from_slice(&bytes);let mutation_id=format!("original-op-{index}");let edit=HistoryEdit{id:format!("original-edit-{index}"),actor:Some("saved-author".into()),started_at:"2026-10-21T12:00:00Z".into(),finished_at:None,verb:Some("zoom".into()),line:None,ops:vec![protocol::OpPayload{text:None,binary:Some(wire)}],inverse:Vec::new(),meta:Some(vec![HistoryOpMeta{op_id:Some(mutation_id),author_id:Some("saved-author".into()),hlt:Some((1,index as i64+1,0)),base_version:index as u64,..Default::default()}]),lane:None};history.edits.try_push(edit).unwrap();}let pack=<State as pack::snapshot::ArtifactPack>::encode_pack_with(&State::default(),&Default::default()).unwrap();let spr=block(store::os_spr::history::encode_history(&history,&Default::default())).unwrap();let source=if framed{let mut bytes=Vec::new();let mut length=pack.len();loop{let byte=(length&127)as u8;length>>=7;bytes.push(byte|if length==0{0}else{128});if length==0{break}}bytes.extend_from_slice(&pack);bytes.extend_from_slice(&spr);WindowConfigPackSource::Framed(bytes)}else{WindowConfigPackSource::Pair(store::os_store::serialization::ArtifactPackFiles{pack,spr,ops:String::new()})};WindowConfigPack{window_id:window.into(),window_kind_id:Owner::WINDOW_KIND_ID.into(),source}}
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:64,maximum_copy_bytes:32768,maximum_capacity_bytes:1<<20,maximum_release_bytes:2<<20,maximum_depth:128}}
fn caller()->OriginalJobFixtureCaller{OriginalJobFixtureCaller::admit(OperationId(3401),Generation(23),RetainedCloneGrant{maximum_items:1<<30,maximum_copy_bytes:1<<29,maximum_capacity_bytes:1<<26,maximum_release_bytes:1<<26,maximum_depth:4096},default_now_us,u64::MAX,1<<28)}
fn turn<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,run:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=observe(||caller.turn_with_decoder(grant(),decoder,run));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes),"native saved Window physical receipt differs: {p:?}; original refusal: {:?}; source cursor {:?}; initializer phase {}",result.as_ref().err(),LAST.with(std::cell::Cell::get),INITIALIZER_PHASE.with(|phase|phase.borrow().clone()));result.unwrap_or_else(|failure|panic!("native saved Window original refusal: {failure:?}; cursor {:?}; initializer {}",LAST.with(std::cell::Cell::get),INITIALIZER_PHASE.with(|phase|phase.borrow().clone())))}
fn finish(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,load:&mut Option<WindowConfigPackLoad>,registry:&mut crate::WindowConfigOwnerRegistry){for index in 0..200000{if load.as_ref().is_none_or(|load|load.terminal_is_empty()){break}note(load);turn(caller,decoder,|cx|cx.with_original_retirement(|cx|registry.close_retained_load_context(load.as_mut().unwrap(),cx).map(|_|())));assert!(index<199999,"saved Window source close stalled");}assert!(load.as_ref().is_none_or(|load|load.terminal_is_empty()));drop(load.take());for index in 0..200000{if registry.terminal_is_empty(){break}note(&None);turn(caller,decoder,|cx|cx.with_original_retirement(|cx|registry.close_step_context(cx.retained_grant(),cx).map(|_|()).map_err(Into::into)));assert!(index<199999,"saved Window registry close stalled");}assert!(registry.terminal_is_empty());while !decoder.terminal_is_empty(){caller.turn(grant(),|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}}
#[test]
fn original_saved_window_native_pair_and_framed_sources_replay_exact_operations(){let law=law();assert_eq!(grant().maximum_copy_bytes,law["maximumHeaderCopyBytes"].as_u64().unwrap()as usize);for source in law["sources"].as_array().unwrap(){let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut registry=crate::WindowConfigOwnerRegistry::new(protocol::ActorId(law["actor"].as_str().unwrap().into()));registry.register::<Owner>().unwrap();let mut pack=Some(input(source=="framed"));let original=pack.as_ref().unwrap().source.pair().unwrap().0.as_ptr();let mut load=None;assert!(turn(&mut caller,&mut decoder,|cx|registry.admit_retained_load(&mut pack,cx,&mut load)),"native saved loader frame={} bytes",size_of::<TypedWindowConfigPackLoad<Owner>>());assert!(pack.is_none());let mut ready=false;for index in 0..law["maximumTurns"].as_u64().unwrap(){note(&load);let step=turn(&mut caller,&mut decoder,|cx|registry.advance_retained_load_context(load.as_mut().unwrap(),cx));if matches!(step,WindowConfigPackLoadStep::Ready){ready=true;break}assert!(!matches!(step,WindowConfigPackLoadStep::Rejected(_)),"saved Window native replay rejected at turn {index}: {step:?}");assert!(index+1<law["maximumTurns"].as_u64().unwrap(),"saved Window native replay stalled");}assert!(ready);assert!(registry.borrow(Owner::WINDOW_KIND_ID,law["window"].as_str().unwrap()).is_none());let typed=load.as_mut().unwrap().inner.as_mut().unwrap().as_any_mut().downcast_mut::<TypedWindowConfigPackLoad<Owner>>().unwrap();let state=typed.candidate.as_ref().unwrap().store.snapshot().unwrap().to_value();let expected=State::from_value(semio_framework_value::DslValue::Object(vec![("zoom".into(),law["zooms"].as_array().unwrap().last().unwrap().as_f64().unwrap().to_value())])).unwrap();assert_eq!(state,expected.to_value());if source=="pair"{assert_eq!(typed.candidate.as_ref().unwrap().store.envelope().vcs.genesis.pack().as_ptr(),original)}for index in 0..200000{note(&load);let step=turn(&mut caller,&mut decoder,|cx|registry.commit_retained_load_context(load.as_mut().unwrap(),cx));assert!(!matches!(step,WindowConfigPackLoadStep::Rejected(_)));if load.as_ref().unwrap().phase()==WindowConfigPackLoadPhase::RetiringDisplacedStore{break}assert!(index<199999);}assert_eq!(registry.borrow(Owner::WINDOW_KIND_ID,law["window"].as_str().unwrap()).unwrap().get::<Owner>().unwrap().to_value(),expected.to_value());finish(&mut caller,&mut decoder,&mut load,&mut registry);caller.retire(grant());}}
#[test]
fn original_saved_window_cancellation_retains_both_original_input_shapes(){let law=law();for framed in[false,true]{for cut in law["cancelAt"].as_array().unwrap(){let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut registry=crate::WindowConfigOwnerRegistry::new(protocol::ActorId("cancel-reader".into()));registry.register::<Owner>().unwrap();let mut pack=Some(input(framed));let mut load=None;assert!(turn(&mut caller,&mut decoder,|cx|registry.admit_retained_load(&mut pack,cx,&mut load)),"native saved loader frame={} bytes",size_of::<TypedWindowConfigPackLoad<Owner>>());for _ in 0..cut.as_u64().unwrap(){note(&load);turn(&mut caller,&mut decoder,|cx|registry.advance_retained_load_context(load.as_mut().unwrap(),cx));}load.as_mut().unwrap().request_cancel();finish(&mut caller,&mut decoder,&mut load,&mut registry);caller.retire(grant());}}}

pub(in crate::retained) fn diagnostic(load:&Option<WindowConfigPackLoad>)->String{note(load);format!("cursor {:?}; initializer {}",LAST.with(std::cell::Cell::get),INITIALIZER_PHASE.with(|phase|phase.borrow().clone()))}

#[test]fn original_saved_window_pair_header_fits_mounted_copy_policy(){let d=Owner::native_pair_demands().unwrap();assert!(d.copy_bytes<=32768,"pair header quote={d:?}, frame={}, snapshot={}, history={}",size_of::<semio_framework_os_store_codec_registry::native_snapshot::OriginalArtifactPairReceiving<State>>(),size_of::<<State as semio_framework_os_store_codec_registry::native_snapshot::OriginalArtifactPackReceiving>::Receiving>(),size_of::<store::os_spr::history::RetainedHistorySourceDecode>());}
